WITH RecentStores AS (SELECT * FROM stores WHERE city IN ('New York', 'London', 'Bangkok')), region_summary AS (SELECT region, ROUND((100 * SUM(CASE WHEN city = 'Berlin' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_berlin, COUNT(CASE WHEN region = 'Central' THEN 1 END) AS central_count FROM RecentStores GROUP BY region) SELECT region, pct_berlin, central_count FROM region_summary WHERE pct_berlin > 23
